UPDATE sys17_corp_account
   SET sys17_bank_cd         = #{req.bankCode},
       sys17_account_no      = #{accountNoEnc},
       sys17_account_nm      = #{req.accountName},
       sys17_main_account_yn = #{req.mainAccountYn}
 WHERE sys17_corp_account_id = #{req.corpAccountId}
   AND sys17_corp_id         = #{corpId}

